from typing import List

def minTimeToReach(moveTime: List[List[int]]) -> int:
    n, m = len(moveTime), len(moveTime[0])
    pq = [(0, 0, 0)]
    dist = [[float('inf')] * m for _ in range(n)]
    dist[0][0] = 0

    while pq:
        t, r, c = heapq.heappop(pq)

        if t > dist[r][c]:
            continue

        if r == n - 1 and c == m - 1:
            return t

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
