from typing import List

def permute(n: int, k: int) -> List[int]:
    # Precompute number of alternating permutations using DP
    # dp[o][e][next_is_odd] = count
    # o: remaining odds, e: remaining evens
    # next_is_odd: 1 if next must be odd, 0 if even
    memo = {}

    def count_ways(o: int, e: int, next_is_odd: int) -> int:
        if o == 0 and e == 0:
            return 1
        state = (o, e, next_is_odd)
        if state in memo:
            return memo[state]

        res = 0
        if next_is_odd:
            if o > 0:
                # We choose one of the 'o' odd numbers.
                # Each choice leaves (o-1, e) and requires an even number next.
                res = o * count_ways(o - 1, e, 0)
        else:
            if e > 0:
                # We choose one of the 'e' even numbers.
                # Each choice leaves (o, e-1) and requires an odd number next.
                res = e * count_ways(o, e - 1, 1)

        memo[state] = res
        return res

    # Iterative DP to avoid RecursionError for n=100
    # dp[o][e][next_is_odd]
    dp = [[[0, 0] for _ in range(n + 1)] for _ in range(n + 1)]
    for o in range(n + 1):
        for e in range(n + 1):
            if o == 0 and e == 0:
                dp[o][e][0] = dp[o][e][1] = 1
            else:
                # If next must be odd (1)
                if o > 0:
                    dp[o][e][1] = o * dp[o-1][e][0]
                # If next must be even (0)
                if e > 0:
                    dp[o][e][0] = e * dp[o][e-1][1]

    current_odds = sum(1 for i in range(1, n + 1) if i % 2 != 0)
    current_evens = sum(1 for i in range(1, n + 1) if i % 2 == 0)

    res = []
    used = [False] * (n + 1)

    for i in range(n):
        found = False
        for v in range(1, n + 1):
            if not used[v]:
                # Parity check: adjacent elements must have different parity
                if i > 0 and (v % 2 == res[-1] % 2):
                    continue

                rem_o = current_odds - (1 if v % 2 != 0 else 0)
                rem_e = current_evens - (1 if v % 2 == 0 else 0)
                next_is_odd = 1 if (v % 2 == 0) else 0

                # Check if we have enough numbers of the required parity left
                if next_is_odd and rem_o < 0: continue
                if not next_is_odd and rem_e < 0: continue

                cnt = dp[rem_o][rem_e][next_is_odd]

                if k <= cnt:
                    res.append(v)
                    used[v] = True
                    current_odds -= (1 if v % 2 != 0 else 0)
                    current_evens -= (1 if v % 2 == 0 else 0)
                    found = True
                    break
                else:
                    k -= cnt
        if not found:
            return []

    return res

