def maxScore(a: List[int], b: List[int]) -> int:
    # dp[i] is the maximum score using first i elements of a
    # Initialize with negative infinity as scores can be negative
    dp = [-float('inf')] * 5
    dp[0] = 0

    for x in b:
        # Update dp from right to left to ensure we use each x only once per subsequence
        # and maintain the strictly increasing index property i_0 < i_1 < i_2 < i_3
        for j in range(4, 0, -1):
            if dp[j-1] != -float('inf'):
                dp[j] = max(dp[j], dp[j-1] + a[j-1] * x)

    return int(dp[4])
