from typing import List
from collections import deque

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # 1. 預處理：使用 BFS 計算所有點（包含起始點與所有棋子位置）之間的最小距離
    all_points = [(kx, ky)] + positions
    n = len(positions)
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        # BFS 從每個點出發計算到其他所有點的距離
        q = deque([(all_points[i], 0)])
        visited = {all_points[i]}
        dist[i][i] = 0
        while q:
            (x, y), d = q.popleft()
            # 如果到達了某個棋子的位置，記錄距離（但繼續搜尋，因為可能有更短路徑到其他點）
            for j in range(n + 1):
                if all_points[j] == (x, y):
                    dist[i][j] = min(dist[i][j], d)

            # 騎士的 8 個移動方向
            for dx, dy in [(2,1), (2,-1), (-1,2), (-1,-2), (-2,1), (-2,-1), (1,2), (1,-2)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    q.append(((nx, ny), d + 1))

    # 2. 狀態壓縮 DP：memo[mask][last_idx] 表示當剩餘棋子為 mask，且騎士目前在 positions[last_idx] 時的結果
    # 使用 -1 表示未計算。初始位置我們用 last_idx = n 代表起始點 (kx, ky)
    memo = {}

    def solve(mask: int, last_idx: int, is_alice: bool) -> int:
        if mask == 0:
            return 0

        state = (mask, last_idx, is_alice)
        if state in memo:
            return memo[state]

        res = float('-inf') if is_alice else float('inf')

        for i in range(n):
            # 如果第 i 個棋子還在場上 (mask 的第 i 位為 1)
            if (mask >> i) & 1:
                # 計算從當前位置到第 i 個棋子的距離
                d = dist[last_idx][i + 1]
                # 遞迴計算剩下的結果
                score = d + solve(mask ^ (1 << i), i + 1, not is_alice)

                if is_alice:
                    res = max(res, score)
                else:
                    res = min(res, score)

        memo[state] = res
        return res

    # 初始化 mask：所有棋子都在 (1 << n) - 1
    # 起始位置是 last_idx = n (對應 all_points[0])
    return solve((1 << n) - 1, n, True)
