    # Try all possible substrings from s and t
    # Substring of s: s[i:j], Substring of t: t[k:l]
    for i in range(n + 1):
        for j in range(i, n + 1):
            s_sub = s[i:j]
            for k in range(m + 1):
                for l in range(k, m + 1):
                    combined = s_sub + t[k:l]
                    # Check if combined is a palindrome
                    if combined == combined[::-1]:
