from typing import List

def minZeroArray(nums: List[int], queries: List[List[int]]) -> int:
    n = len(nums)

    # If already zero, return 0
    if all(x == 0 for x in nums):
        return 0

    for k in range(1, len(queries) + 1):
        possible = True
        # For each index j in the array, check if we can reach exactly nums[j]
        # using a subset of queries from the first k queries that cover index j.
        for j in range(n):
            target = nums[j]
            if target == 0:
                continue

            # Collect all values from valid queries covering this specific index
            available_vals = []
            for i in range(k):
                l, r, val = queries[i]
                if l <= j <= r:
                    available_vals.append(val)

            # Standard subset sum DP to see if target can be formed
            dp = [False] * (target + 1)
            dp[0] = True
            for v in available_vals:
                for s in range(target, v - 1, -1):
                    if dp[s - v]:
                        dp[s] = True
                if dp[target]:
                    break

            # If any index cannot be reduced to zero, this k is invalid
            if not dp[target]:
                possible = False
                break

        if possible:
            return k

    return -1
